+/// A searcher that never matches. Used for hooks whose equalities are
+/// subsumed by the fused rules below.
+struct NeverMatches;
+
+impl Searcher<Language, MyAnalysis> for NeverMatches {
+    fn search_eclass(&self, _egraph: &EG, _eclass: Id) -> Option<SearchMatches<Language>> {
+        None
+    }
+
+    fn search(&self, _egraph: &EG) -> Vec<SearchMatches<Language>> {
+        Vec::new()
+    }
+
+    fn vars(&self) -> Vec<Var> {
+        Vec::new()
+    }
+}
+
+/// An applier that adds nothing.
+struct AppliesNothing;
+
+impl Applier<Language, MyAnalysis> for AppliesNothing {
+    fn apply_one(
+        &self,
+        _egraph: &mut EG,
+        _eclass: Id,
+        _subst: &Subst,
+        _searcher_ast: Option<&PatternAst<Language>>,
+        _rule_name: Symbol,
+    ) -> Vec<Id> {
+        Vec::new()
+    }
+}
+
+fn never_fires(name: &str) -> RW {
+    Rewrite::new(name, NeverMatches, AppliesNothing).unwrap()
+}
+
+/// A pattern searcher that only reports the matches accepted by `keep`.
+struct FilteredPattern<F> {
+    pattern: Pattern<Language>,
+    keep: F,
+}
+
+impl<F> Searcher<Language, MyAnalysis> for FilteredPattern<F>
+where
+    F: Fn(&EG, Id, &Subst) -> bool,
+{
+    fn search_eclass(&self, egraph: &EG, eclass: Id) -> Option<SearchMatches<Language>> {
+        let mut matches = self.pattern.search_eclass(egraph, eclass)?;
+        matches.substs.retain(|subst| (self.keep)(egraph, eclass, subst));
+        if matches.substs.is_empty() {
+            None
+        } else {
+            Some(matches)
+        }
+    }
+
+    fn search(&self, egraph: &EG) -> Vec<SearchMatches<Language>> {
+        let mut all = self.pattern.search(egraph);
+        for matches in all.iter_mut() {
+            let eclass = matches.eclass;
+            matches.substs.retain(|subst| (self.keep)(egraph, eclass, subst));
+        }
+        all.retain(|matches| !matches.substs.is_empty());
+        all
+    }
+
+    fn vars(&self) -> Vec<Var> {
+        self.pattern.vars()
+    }
+}
+
+fn has_node(egraph: &EG, eclass: Id, test: impl Fn(&Language) -> bool) -> bool {
+    egraph[eclass].nodes.iter().any(test)
+}
+
+/// Whether a dot product of the Cartesian product of `left` and `right`
+/// already multiplies vectors by a matrix.
+fn operands_have_matrix_form(egraph: &EG, left: Id, right: Id) -> bool {
+    match (&egraph[left].data, &egraph[right].data) {
+        (MyAnalysisData::AccessPattern(l), MyAnalysisData::AccessPattern(r)) => {
+            l.shape.ndim() <= 1
+                && l.item_shape.ndim() == 1
+                && r.shape.ndim() == 1
+                && r.item_shape.ndim() == 1
+        }
+        _ => false,
+    }
+}
+
+/// The shape facts of an access-pattern e-class.
+fn access_shapes(egraph: &EG, id: Id) -> Option<(Vec<usize>, Vec<usize>)> {
+    match &egraph[id].data {
+        MyAnalysisData::AccessPattern(a) => {
+            Some((a.shape.slice().to_vec(), a.item_shape.slice().to_vec()))
+        }
+        _ => None,
+    }
+}
+
+fn add_shape_literal(egraph: &mut EG, dims: &[usize]) -> Id {
+    let ids = dims
+        .iter()
+        .map(|&d| egraph.add(Language::Num(d as i64)))
+        .collect::<Vec<_>>();
+    egraph.add(Language::Shape(ids.into_boxed_slice()))
+}
+
+/// For `(compute dot-product (access-cartesian-product left right))`, builds
+/// the same dot products over flattened operands, so that the left operand
+/// has at most one outer dimension, the right operand has exactly one, and
+/// both have one-dimensional items. The result is reshaped back to the
+/// original outer shape. Flattening is row-major, so every pair of items is
+/// still multiplied elementwise and summed, and lands at the same position.
+///
+/// Returns `None` when the operands already have that form or when the match
+/// is not a well-formed dot product of a Cartesian product.
+fn flattened_dot_product(egraph: &mut EG, dot_product: Id, left: Id, right: Id) -> Option<Id> {
+    let ((left_outer, left_item), (right_outer, right_item)) =
+        match (access_shapes(egraph, left), access_shapes(egraph, right)) {
+            (Some(l), Some(r)) => (l, r),
+            _ => return None,
+        };
+    if left_item != right_item || left_item.is_empty() {
+        return None;
+    }
+    let flatten_left = !(left_outer.len() <= 1 && left_item.len() == 1);
+    let flatten_right = !(right_outer.len() == 1 && right_item.len() == 1);
+    if !(flatten_left || flatten_right) {
+        return None;
+    }
+    // Flattening an access without outer dimensions is not needed by any
+    // well-formed matrix product and is left alone.
+    if (flatten_left && left_outer.is_empty()) || (flatten_right && right_outer.is_empty()) {
+        return None;
+    }
+
+    let outer = left_outer
+        .iter()
+        .chain(right_outer.iter())
+        .cloned()
+        .collect::<Vec<_>>();
+    let mut flat_outer = Vec::with_capacity(2);
+    if flatten_left {
+        flat_outer.push(left_outer.iter().product::<usize>());
+    } else {
+        flat_outer.extend(left_outer.iter().cloned());
+    }
+    if flatten_right {
+        flat_outer.push(right_outer.iter().product::<usize>());
+    } else {
+        flat_outer.extend(right_outer.iter().cloned());
+    }
+
+    let left = if flatten_left {
+        egraph.add(Language::AccessFlatten(left))
+    } else {
+        left
+    };
+    let right = if flatten_right {
+        egraph.add(Language::AccessFlatten(right))
+    } else {
+        right
+    };
+    let product = egraph.add(Language::AccessCartesianProduct([left, right]));
+    let compute = egraph.add(Language::Compute([dot_product, product]));
+    if flat_outer == outer {
+        return Some(compute);
+    }
+    let outer_id = add_shape_literal(egraph, &outer);
+    let item_id = add_shape_literal(egraph, &[]);
+    let access_shape = egraph.add(Language::AccessShape([outer_id, item_id]));
+    Some(egraph.add(Language::AccessReshape([compute, access_shape])))
+}
+
+fn add_zero_pad(egraph: &mut EG, access: Id, axis: usize, before: usize, after: usize) -> Id {
+    let pad_type = egraph.add(Language::PadType(PadType::ZeroPadding));
+    let axis = egraph.add(Language::Num(axis as i64));
+    let before = egraph.add(Language::Num(before as i64));
+    let after = egraph.add(Language::Num(after as i64));
+    egraph.add(Language::AccessPad([access, pad_type, axis, before, after]))
+}
+
+/// The operands of the Cartesian-product nodes in an e-class.
+fn cartesian_operands(egraph: &EG, eclass: Id) -> Vec<(Id, Id)> {
+    egraph[eclass]
+        .nodes
+        .iter()
+        .filter_map(|node| match node {
+            Language::AccessCartesianProduct([l, r]) => Some((*l, *r)),
+            _ => None,
+        })
+        .collect()
+}
+
+/// For the concatenation, along outer axis `axis`, of the dot products of
+/// `(access-cartesian-product l0 r0)` and `(access-cartesian-product l1 r1)`,
+/// builds one dot product of block operands.
+///
+/// When the axis is one of the left operands' outer axes, the right operands
+/// are concatenated along their first item axis, and the left operands are
+/// zero-padded along that item axis (l0's items fill the first half and l1's
+/// the second) and then concatenated along `axis`. Every result then pairs
+/// l0 with r0 or l1 with r1, and the padding only adds zero products. The
+/// right-axis case is symmetric. The result is in matrix form when possible.
+fn block_dot_product(
+    egraph: &mut EG,
+    dot_product: Id,
+    (l0, r0): (Id, Id),
+    (l1, r1): (Id, Id),
+    axis: usize,
+) -> Option<Id> {
+    let (left_outer0, left_item0) = access_shapes(egraph, l0)?;
+    let (right_outer0, right_item0) = access_shapes(egraph, r0)?;
+    let (left_outer1, left_item1) = access_shapes(egraph, l1)?;
+    let (right_outer1, right_item1) = access_shapes(egraph, r1)?;
+    if left_item0.is_empty()
+        || left_item0 != right_item0
+        || left_item0 != left_item1
+        || left_item0 != right_item1
+        || left_outer0.len() != left_outer1.len()
+        || right_outer0.len() != right_outer1.len()
+    {
+        return None;
+    }
+    let left_rank = left_outer0.len();
+    let right_rank = right_outer0.len();
+    if axis >= left_rank + right_rank {
+        return None;
+    }
+    let equal_except = |a: &[usize], b: &[usize], at: usize| {
+        a.iter().zip(b.iter()).enumerate().all(|(i, (x, y))| i == at || x == y)
+    };
+    let half = left_item0[0];
+    let (left, right) = if axis < left_rank {
+        if right_outer0 != right_outer1 || !equal_except(&left_outer0, &left_outer1, axis) {
+            return None;
+        }
+        let padded0 = add_zero_pad(egraph, l0, left_rank, 0, half);
+        let padded1 = add_zero_pad(egraph, l1, left_rank, half, 0);
+        let axis_id = egraph.add(Language::Num(axis as i64));
+        let left = egraph.add(Language::AccessConcatenate([padded0, padded1, axis_id]));
+        let item_axis = egraph.add(Language::Num(right_rank as i64));
+        let right = egraph.add(Language::AccessConcatenate([r0, r1, item_axis]));
+        (left, right)
+    } else {
+        let axis = axis - left_rank;
+        if left_outer0 != left_outer1 || !equal_except(&right_outer0, &right_outer1, axis) {
+            return None;
+        }
+        let item_axis = egraph.add(Language::Num(left_rank as i64));
+        let left = egraph.add(Language::AccessConcatenate([l0, l1, item_axis]));
+        let padded0 = add_zero_pad(egraph, r0, right_rank, 0, half);
+        let padded1 = add_zero_pad(egraph, r1, right_rank, half, 0);
+        let axis_id = egraph.add(Language::Num(axis as i64));
+        let right = egraph.add(Language::AccessConcatenate([padded0, padded1, axis_id]));
+        (left, right)
+    };
+    Some(match flattened_dot_product(egraph, dot_product, left, right) {
+        Some(id) => id,
+        None => {
+            let product = egraph.add(Language::AccessCartesianProduct([left, right]));
+            egraph.add(Language::Compute([dot_product, product]))
+        }
+    })
+}
+
+fn add_dot_product_type(egraph: &mut EG) -> Id {
+    egraph.add(Language::ComputeType(ComputeType::DotProduct))
+}
+
+fn union_if_new(egraph: &mut EG, eclass: Id, id: Id) -> Vec<Id> {
+    if egraph.union(eclass, id) {
+        vec![eclass]
+    } else {
+        Vec::new()
+    }
+}
+
