diff --git a/code/src/language/solver_extensions/access_analysis.rs b/code/src/language/solver_extensions/access_analysis.rs
index e711714..4ef9152 100644
--- a/code/src/language/solver_extensions/access_analysis.rs
+++ b/code/src/language/solver_extensions/access_analysis.rs
@@ -1,13 +1,976 @@
+// Compositional access-pattern analysis.
+//
+// This file is spliced into the end of `language.rs`, so it shares that
+// module's imports and private items.
+
+/// Builds an access-pattern fact with no known zero regions.
+fn aa_access_data(
+    shape: IxDyn,
+    item_shape: IxDyn,
+    settled: bool,
+    contains_accelerator_calls: bool,
+) -> MyAnalysisData {
+    MyAnalysisData::AccessPattern(AccessPatternData {
+        shape,
+        item_shape,
+        zero_regions: HashMap::default(),
+        access_pattern_shape_settled: settled,
+        contains_accelerator_calls,
+    })
+}
+
+/// Builds an access-pattern fact from a full tensor shape and an access axis.
+fn aa_access_from_vec(
+    full: &[usize],
+    access_axis: usize,
+    settled: bool,
+    contains_accelerator_calls: bool,
+) -> MyAnalysisData {
+    aa_access_data(
+        IxDyn(&full[..access_axis]),
+        IxDyn(&full[access_axis..]),
+        settled,
+        contains_accelerator_calls,
+    )
+}
+
+fn aa_access<'a>(egraph: &'a EGraph<Language, MyAnalysis>, id: Id) -> &'a AccessPatternData {
+    match &egraph[id].data {
+        MyAnalysisData::AccessPattern(a) => a,
+        other => panic!("expected an access pattern, found {:?}", other),
+    }
+}
+
+/// Returns the shape described by a shape-like fact: a shape literal, a
+/// symbol's shape, or the full shape of an access pattern.
+fn aa_shape_vec(egraph: &EGraph<Language, MyAnalysis>, id: Id) -> Vec<usize> {
+    match &egraph[id].data {
+        MyAnalysisData::Shape(s) => s.shape.slice().to_vec(),
+        MyAnalysisData::AccessPattern(a) => a.as_vec(),
+        MyAnalysisData::List(l) => l.clone(),
+        other => panic!("expected a shape, found {:?}", other),
+    }
+}
+
+fn aa_list(egraph: &EGraph<Language, MyAnalysis>, id: Id) -> Vec<usize> {
+    match &egraph[id].data {
+        MyAnalysisData::List(l) => l.clone(),
+        MyAnalysisData::Shape(s) => s.shape.slice().to_vec(),
+        MyAnalysisData::Num(v) => vec![usize::try_from(*v).unwrap()],
+        other => panic!("expected a list, found {:?}", other),
+    }
+}
+
+fn aa_literal_f64(egraph: &EGraph<Language, MyAnalysis>, id: Id) -> f64 {
+    match &egraph[id].data {
+        MyAnalysisData::Literal(l) => l.iter().next().cloned().unwrap_or(0.0),
+        MyAnalysisData::Num(v) => *v as f64,
+        other => panic!("expected a literal, found {:?}", other),
+    }
+}
+
+fn aa_contains_accelerator_calls(data: &MyAnalysisData) -> bool {
+    match data {
+        MyAnalysisData::AccessPattern(a) => a.contains_accelerator_calls,
+        MyAnalysisData::Tuple(t) => t.iter().any(aa_contains_accelerator_calls),
+        _ => false,
+    }
+}
+
+/// Numpy-style broadcast of two shapes.
+fn aa_broadcast_shapes(a: &[usize], b: &[usize]) -> Vec<usize> {
+    let n = std::cmp::max(a.len(), b.len());
+    (0..n)
+        .map(|i| {
+            let x = if i + a.len() >= n { a[i + a.len() - n] } else { 1 };
+            let y = if i + b.len() >= n { b[i + b.len() - n] } else { 1 };
+            if x == 1 {
+                y
+            } else if y == 1 || x == y {
+                x
+            } else {
+                panic!("cannot broadcast shapes {:?} and {:?}", a, b)
+            }
+        })
+        .collect()
+}
+
+/// Output extent of a pooling or convolution window along one dimension.
+fn aa_window_extent(input: usize, pad: usize, kernel: usize, stride: usize) -> usize {
+    (input + pad - kernel) / stride + 1
+}
