+fn aa_relay_operator_call(egraph: &EGraph<Language, MyAnalysis>, params: &[Id]) -> MyAnalysisData {
+    assert!(!params.is_empty(), "relay operator call requires an operator");
+    let op = match &egraph[params[0]].data {
+        MyAnalysisData::RelayOperator(op) => op.clone(),
+        other => panic!("expected a relay operator, found {:?}", other),
+    };
+    let args = &params[1..];
+    let contains = args
+        .iter()
+        .any(|id| aa_contains_accelerator_calls(&egraph[*id].data));
+    let out = |shape: Vec<usize>| aa_access_data(IxDyn(&shape), IxDyn(&[]), false, contains);
+    let data_shape = |i: usize| aa_shape_vec(egraph, args[i]);
+    let layout = |i: usize| match &egraph[args[i]].data {
+        MyAnalysisData::RelayActivationLayout(l) => l.clone(),
+        _ => RelayActivationLayout::NCHW,
+    };
+
+    match op {
+        RelayOperator::RelaySoftmax
+        | RelayOperator::RelayLogSoftmax
+        | RelayOperator::RelayReLU
+        | RelayOperator::RelayLeakyReLU
+        | RelayOperator::RelayErf
+        | RelayOperator::RelaySigmoid
+        | RelayOperator::RelayTanh
+        | RelayOperator::RelaySqrt
+        | RelayOperator::RelayNegative
+        | RelayOperator::RelayRound
+        | RelayOperator::RelayCopy
+        | RelayOperator::RelayCast
+        | RelayOperator::RelayClip
+        | RelayOperator::RelayLeftShift
+        | RelayOperator::RelayRightShift
+        | RelayOperator::RelayDropout
+        | RelayOperator::RelayBiasAdd
+        | RelayOperator::RelayLayerNorm
+        | RelayOperator::RelayBatchNormInference => out(data_shape(0)),
+        RelayOperator::RelayAdd
+        | RelayOperator::RelayMultiply
+        | RelayOperator::RelayDivide
+        | RelayOperator::RelayMaximum
+        | RelayOperator::RelayMinimum => out(aa_broadcast_shapes(&data_shape(0), &data_shape(1))),
+        RelayOperator::RelayDense => {
+            let data = data_shape(0);
+            let weight = data_shape(1);
+            out(vec![data[0], weight[0]])
+        }
+        RelayOperator::RelayBatchMatmul => {
+            let a = data_shape(0);
+            let b = data_shape(1);
+            out(vec![a[0], a[1], b[1]])
+        }
+        RelayOperator::RelayBatchFlatten => {
+            let data = data_shape(0);
+            out(vec![data[0], data[1..].iter().product()])
+        }
+        RelayOperator::RelayReshape | RelayOperator::RelayZeros => {
+            let last = if op == RelayOperator::RelayZeros { 0 } else { 1 };
+            out(data_shape(last))
+        }
+        RelayOperator::RelayMean => {
+            let mut data = data_shape(0);
+            let axis = MyAnalysis::get_usize(args[1], egraph);
+            data.remove(axis);
+            out(data)
+        }
+        RelayOperator::RelayMaxPool2D | RelayOperator::RelayAvgPool2D => {
+            let data = data_shape(0);
+            let pool = aa_shape_vec(egraph, args[1]);
+            let strides = aa_shape_vec(egraph, args[2]);
+            let padding = aa_shape_vec(egraph, args[3]);
+            match layout(4) {
+                RelayActivationLayout::NCHW => out(vec![
+                    data[0],
+                    data[1],
+                    aa_window_extent(data[2], padding[0] + padding[2], pool[0], strides[0]),
+                    aa_window_extent(data[3], padding[1] + padding[3], pool[1], strides[1]),
+                ]),
+                RelayActivationLayout::NHWC => out(vec![
+                    data[0],
+                    aa_window_extent(data[1], padding[0] + padding[2], pool[0], strides[0]),
+                    aa_window_extent(data[2], padding[1] + padding[3], pool[1], strides[1]),
+                    data[3],
+                ]),
+            }
+        }
+        RelayOperator::RelayGlobalAvgPool2D => {
+            let data = data_shape(0);
+            match layout(1) {
+                RelayActivationLayout::NCHW => out(vec![data[0], data[1], 1, 1]),
+                RelayActivationLayout::NHWC => out(vec![data[0], 1, 1, data[3]]),
+            }
+        }
+        RelayOperator::RelayUpSampling => {
+            let data = data_shape(0);
+            let scale_h = aa_literal_f64(egraph, args[1]);
+            let scale_w = aa_literal_f64(egraph, args[2]);
+            let scale = |v: usize, s: f64| ((v as f64) * s).round() as usize;
+            match layout(3) {
+                RelayActivationLayout::NCHW => out(vec![
+                    data[0],
+                    data[1],
+                    scale(data[2], scale_h),
+                    scale(data[3], scale_w),
+                ]),
+                RelayActivationLayout::NHWC => out(vec![
+                    data[0],
+                    scale(data[1], scale_h),
+                    scale(data[2], scale_w),
+                    data[3],
+                ]),
+            }
+        }
+        RelayOperator::RelayConv1D => {
+            let data = data_shape(0);
+            let kernel = data_shape(1);
+            let strides = aa_shape_vec(egraph, args[2]);
+            let padding = aa_shape_vec(egraph, args[3]);
+            out(vec![
+                data[0],
+                kernel[0],
+                aa_window_extent(data[2], padding[0] + padding[1], kernel[2], strides[0]),
+            ])
+        }
+        RelayOperator::RelayConv2D => {
+            let data = data_shape(0);
+            let kernel = data_shape(1);
+            let strides = aa_shape_vec(egraph, args[2]);
+            let padding = aa_shape_vec(egraph, args[3]);
+            let kernel_layout = match &egraph[args[8]].data {
+                MyAnalysisData::RelayKernelLayout(l) => l.clone(),
+                _ => RelayKernelLayout::OIHW,
+            };
+            let (o, kh, kw) = match kernel_layout {
+                RelayKernelLayout::OIHW => (kernel[0], kernel[2], kernel[3]),
+                RelayKernelLayout::HWIO => (kernel[3], kernel[0], kernel[1]),
+            };
+            match layout(7) {
+                RelayActivationLayout::NCHW => out(vec![
+                    data[0],
+                    o,
+                    aa_window_extent(data[2], padding[0] + padding[2], kh, strides[0]),
+                    aa_window_extent(data[3], padding[1] + padding[3], kw, strides[1]),
+                ]),
+                RelayActivationLayout::NHWC => out(vec![
+                    data[0],
+                    aa_window_extent(data[1], padding[0] + padding[2], kh, strides[0]),
+                    aa_window_extent(data[2], padding[1] + padding[3], kw, strides[1]),
+                    o,
+                ]),
+            }
+        }
+        RelayOperator::RelaySplit => {
+            let data = data_shape(0);
+            let sections = MyAnalysis::get_usize(args[1], egraph);
+            let axis = MyAnalysis::get_usize(args[2], egraph);
+            let mut piece = data.clone();
+            piece[axis] = data[axis] / sections;
+            MyAnalysisData::Tuple((0..sections).map(|_| out(piece.clone())).collect())
+        }
+        RelayOperator::RelayTake => {
+            let data = data_shape(0);
+            let indices = data_shape(1);
+            let axis = MyAnalysis::get_usize(args[2], egraph);
+            out(data[..axis]
+                .iter()
+                .chain(indices.iter())
+                .chain(data[axis + 1..].iter())
+                .cloned()
+                .collect())
+        }
+        RelayOperator::RelayStack => {
+            let axis = MyAnalysis::get_usize(args[args.len() - 1], egraph);
+            let inputs = &args[..args.len() - 1];
+            let mut shape = match &egraph[inputs[0]].data {
+                MyAnalysisData::Tuple(t) => match &t[0] {
+                    MyAnalysisData::AccessPattern(a) => {
+                        let mut v = a.as_vec();
+                        v.insert(axis, t.len());
+                        return out(v);
+                    }
+                    other => panic!("expected an access pattern, found {:?}", other),
+                },
+                _ => data_shape(0),
+            };
+            shape.insert(axis, inputs.len());
+            out(shape)
+        }
+        RelayOperator::RelayStridedSlice => {
+            let data = data_shape(0);
+            let begin = aa_shape_vec(egraph, args[1]);
+            let end = aa_shape_vec(egraph, args[2]);
+            let strides = aa_shape_vec(egraph, args[3]);
+            out((0..data.len())
+                .map(|i| {
+                    if i < begin.len() {
+                        let end = std::cmp::min(end[i], data[i]);
+                        let stride = if i < strides.len() { strides[i] } else { 1 };
+                        (end - begin[i] + stride - 1) / stride
+                    } else {
+                        data[i]
+                    }
+                })
+                .collect())
+        }
+        RelayOperator::RelayExpandDims => {
+            let mut data = data_shape(0);
+            let axis = MyAnalysis::get_usize(args[1], egraph);
+            let count = if args.len() > 2 {
+                MyAnalysis::get_usize(args[2], egraph)
+            } else {
+                1
+            };
+            for _ in 0..count {
+                data.insert(axis, 1);
+            }
+            out(data)
+        }
+        RelayOperator::RelayPad => {
+            let data = data_shape(0);
+            let widths = aa_shape_vec(egraph, args[1]);
+            out(data
+                .iter()
+                .enumerate()
+                .map(|(i, d)| d + widths[2 * i] + widths[2 * i + 1])
+                .collect())
+        }
+        RelayOperator::RelayConcatenate => {
+            let axis = MyAnalysis::get_usize(args[1], egraph);
+            let parts: Vec<Vec<usize>> = match &egraph[args[0]].data {
+                MyAnalysisData::Tuple(t) => t
+                    .iter()
+                    .map(|d| match d {
+                        MyAnalysisData::AccessPattern(a) => a.as_vec(),
+                        other => panic!("expected an access pattern, found {:?}", other),
+                    })
+                    .collect(),
+                _ => vec![data_shape(0)],
+            };
+            let mut shape = parts[0].clone();
+            shape[axis] = parts.iter().map(|p| p[axis]).sum();
+            out(shape)
+        }
+        RelayOperator::RelayTranspose => {
+            let data = data_shape(0);
+            let axes = aa_list(egraph, args[1]);
+            out(axes.iter().map(|&i| data[i]).collect())
+        }
+        RelayOperator::RelaySqueeze => {
+            let data = data_shape(0);
+            let axes = aa_list(egraph, args[1]);
+            out(data
+                .iter()
+                .enumerate()
+                .filter(|(i, _)| !axes.contains(i))
+                .map(|(_, d)| *d)
+                .collect())
+        }
+    }
+}
