+fn aa_accelerator_call(egraph: &EGraph<Language, MyAnalysis>, ids: &[Id]) -> MyAnalysisData {
+    assert!(ids.len() >= 2, "accelerator call requires a function and a shape");
+    match &egraph[ids[0]].data {
+        MyAnalysisData::AcceleratorFunc(_) => (),
+        other => panic!("expected an accelerator function, found {:?}", other),
+    }
+    match &egraph[ids[ids.len() - 1]].data {
+        MyAnalysisData::AccessPattern(a) => {
+            aa_access_data(a.shape.clone(), a.item_shape.clone(), false, true)
+        }
+        MyAnalysisData::Shape(s) => aa_access_data(s.shape.clone(), IxDyn(&[]), false, true),
+        MyAnalysisData::Tuple(t) => MyAnalysisData::Tuple(
+            t.iter()
+                .map(|d| match d {
+                    MyAnalysisData::AccessPattern(a) => {
+                        aa_access_data(a.shape.clone(), a.item_shape.clone(), false, true)
+                    }
+                    MyAnalysisData::Shape(s) => {
+                        aa_access_data(s.shape.clone(), IxDyn(&[]), false, true)
+                    }
+                    other => other.clone(),
+                })
+                .collect(),
+        ),
+        other => panic!("expected an output shape, found {:?}", other),
+    }
+}
