+fn aa_systolic_array(
+    egraph: &EGraph<Language, MyAnalysis>,
+    blocking: bool,
+    [rows_id, cols_id, a0_id, a1_id]: [Id; 4],
+) -> MyAnalysisData {
+    let rows = MyAnalysis::get_usize(rows_id, egraph);
+    let cols = MyAnalysis::get_usize(cols_id, egraph);
+    let a0 = aa_access(egraph, a0_id);
+    let a1 = aa_access(egraph, a1_id);
+
+    assert_eq!(a1.shape.ndim(), 0);
+    assert!(a0.shape.ndim() <= 1);
+    assert_eq!(a0.item_shape.ndim(), 1);
+    assert_eq!(a1.item_shape.ndim(), 2);
+    assert_eq!(a0.item_shape[0], a1.item_shape[0]);
+    if blocking {
+        assert_eq!(a0.item_shape[0] % rows, 0);
+        assert_eq!(a1.item_shape[1] % cols, 0);
+    } else {
+        assert_eq!(a1.item_shape.slice(), &[rows, cols]);
+    }
+
+    let mut shape = a0.shape.slice().to_vec();
+    shape.push(a1.item_shape[1]);
+    aa_access_data(
+        IxDyn(&shape),
+        IxDyn(&[]),
+        a0.access_pattern_shape_settled && a1.access_pattern_shape_settled,
+        a0.contains_accelerator_calls || a1.contains_accelerator_calls,
+    )
+}
+
+fn aa_systolic_array_conv2d(
+    egraph: &EGraph<Language, MyAnalysis>,
+    nhwc: bool,
+    ids: &[Id; 8],
+) -> MyAnalysisData {
+    let [_rows_id, _cols_id, weights_id, data_id, kh_id, kw_id, stride_h_id, stride_w_id] = *ids;
+    let weights = aa_access(egraph, weights_id);
+    let data = aa_access(egraph, data_id);
+    let kh = MyAnalysis::get_usize(kh_id, egraph);
+    let kw = MyAnalysis::get_usize(kw_id, egraph);
+    let stride_h = MyAnalysis::get_usize(stride_h_id, egraph);
+    let stride_w = MyAnalysis::get_usize(stride_w_id, egraph);
+    let w = weights.as_vec();
+    let d = data.as_vec();
+    assert_eq!(w.len(), 4);
+    assert_eq!(d.len(), 4);
+    let shape = if nhwc {
+        // Data NHWC, weights HWIO.
+        vec![
+            d[0],
+            aa_window_extent(d[1], 0, kh, stride_h),
+            aa_window_extent(d[2], 0, kw, stride_w),
+            w[3],
+        ]
+    } else {
+        // Data NCHW, weights OIHW.
+        vec![
+            d[0],
+            w[0],
+            aa_window_extent(d[2], 0, kh, stride_h),
+            aa_window_extent(d[3], 0, kw, stride_w),
+        ]
+    };
+    aa_access_data(
+        IxDyn(&shape),
+        IxDyn(&[]),
+        weights.access_pattern_shape_settled && data.access_pattern_shape_settled,
+        weights.contains_accelerator_calls || data.contains_accelerator_calls,
+    )
+}
