+fn aa_compute(egraph: &EGraph<Language, MyAnalysis>, [op_id, access_id]: [Id; 2]) -> MyAnalysisData {
+    let compute_type = match &egraph[op_id].data {
+        MyAnalysisData::ComputeType(t) => t,
+        other => panic!("expected a compute type, found {:?}", other),
+    };
+    let a = aa_access(egraph, access_id);
+    let settled = a.access_pattern_shape_settled;
+    let contains = a.contains_accelerator_calls;
+    match compute_type {
+        ComputeType::DotProduct => {
+            assert!(
+                a.item_shape.ndim() >= 1,
+                "dot product requires at least one item dimension"
+            );
+            aa_access_data(a.shape.clone(), IxDyn(&[]), settled, contains)
+        }
+        ComputeType::ReduceSum | ComputeType::ReduceMax | ComputeType::ReduceMean => {
+            aa_access_data(a.shape.clone(), IxDyn(&[]), settled, contains)
+        }
+        ComputeType::ElementwiseAdd | ComputeType::ElementwiseMul | ComputeType::ElementwiseDiv => {
+            assert!(
+                a.item_shape.ndim() >= 1,
+                "elementwise computes require at least one item dimension"
+            );
+            aa_access_data(
+                a.shape.clone(),
+                IxDyn(&a.item_shape.slice()[1..]),
+                settled,
+                contains,
+            )
+        }
+        ComputeType::ReLU | ComputeType::Sqrt | ComputeType::Negative | ComputeType::Softmax => {
+            aa_access_data(a.shape.clone(), a.item_shape.clone(), settled, contains)
+        }
+    }
+}
