+/// Merges two facts for the same e-class into `to`, reporting exactly whether
+/// `to` changed and whether the result differs from `from`.
+fn aa_merge(to: &mut MyAnalysisData, from: MyAnalysisData) -> DidMerge {
+    match (to, from) {
+        (MyAnalysisData::AccessPattern(to), MyAnalysisData::AccessPattern(from)) => {
+            assert_eq!(
+                to.shape.size() * to.item_shape.size(),
+                from.shape.size() * from.item_shape.size(),
+                "merged access patterns must have the same number of elements: {:?} {:?} vs {:?} {:?}",
+                to.shape,
+                to.item_shape,
+                from.shape,
+                from.item_shape,
+            );
+            let same_shape = to.shape == from.shape && to.item_shape == from.item_shape;
+            let mut to_changed = false;
+            let mut from_differs = false;
+            match (
+                to.access_pattern_shape_settled,
+                from.access_pattern_shape_settled,
+            ) {
+                (true, true) => {
+                    assert!(
+                        same_shape,
+                        "settled access patterns disagree: {:?} {:?} vs {:?} {:?}",
+                        to.shape,
+                        to.item_shape,
+                        from.shape,
+                        from.item_shape,
+                    );
+                }
+                (false, true) => {
+                    if !same_shape {
+                        to.shape = from.shape.clone();
+                        to.item_shape = from.item_shape.clone();
+                    }
+                    to.access_pattern_shape_settled = true;
+                    to_changed = true;
+                }
+                (true, false) => from_differs = true,
+                (false, false) => from_differs |= !same_shape,
+            }
+            if from.contains_accelerator_calls && !to.contains_accelerator_calls {
+                to.contains_accelerator_calls = true;
+                to_changed = true;
+            } else if to.contains_accelerator_calls && !from.contains_accelerator_calls {
+                from_differs = true;
+            }
+            // The target's zero regions are preserved as they are.
+            from_differs |= to.zero_regions != from.zero_regions;
+            DidMerge(to_changed, from_differs)
+        }
+        (MyAnalysisData::Tuple(to), MyAnalysisData::Tuple(from)) => {
+            assert_eq!(to.len(), from.len(), "merged tuples must have equal lengths");
+            let mut result = DidMerge(false, false);
+            for (to, from) in to.iter_mut().zip(from.into_iter()) {
+                result = result | aa_merge(to, from);
+            }
+            result
+        }
+        (MyAnalysisData::Shape(to), MyAnalysisData::Shape(from)) => {
+            assert_eq!(to.shape, from.shape, "merged shapes must be equal");
+            DidMerge(false, to.dtype != from.dtype)
+        }
+        (to, from) => {
+            assert_eq!(*to, from, "merged facts must be equal");
+            DidMerge(false, false)
+        }
+    }
+}
