+            Language::Shape(ids) => MyAnalysisData::Shape(ShapeData {
+                shape: IxDyn(
+                    &ids.iter()
+                        .map(|id| MyAnalysis::get_usize(*id, egraph))
+                        .collect::<Vec<_>>(),
+                ),
+                dtype: DataType::Uint(64),
+            }),
+            Language::List(ids) => MyAnalysisData::List(
+                ids.iter()
+                    .map(|id| MyAnalysis::get_usize(*id, egraph))
+                    .collect(),
+            ),
+            Language::ConstructTuple(ids) => {
+                MyAnalysisData::Tuple(ids.iter().map(|id| egraph[*id].data.clone()).collect())
+            }
+            &Language::TupleGetItem([tuple_id, index_id]) => {
+                let index = MyAnalysis::get_usize(index_id, egraph);
+                match &egraph[tuple_id].data {
+                    MyAnalysisData::Tuple(t) => t[index].clone(),
+                    other => panic!("expected a tuple, found {:?}", other),
+                }
+            }
+            &Language::Literal(id) => match &egraph[id].data {
+                MyAnalysisData::Literal(l) => MyAnalysisData::Literal(l.clone()),
+                other => panic!("expected a literal, found {:?}", other),
+            },
+            &Language::AccessLiteral(id) => match &egraph[id].data {
+                MyAnalysisData::Literal(l) => {
+                    aa_access_data(IxDyn(l.shape()), IxDyn(&[]), true, false)
+                }
+                other => panic!("expected a literal, found {:?}", other),
+            },
+            &Language::ConstantTensor([value_id, shape_id]) => {
+                match &egraph[value_id].data {
+                    MyAnalysisData::Literal(_) | MyAnalysisData::Num(_) => (),
+                    other => panic!("expected a literal, found {:?}", other),
+                }
+                aa_access_data(
+                    IxDyn(&aa_shape_vec(egraph, shape_id)),
+                    IxDyn(&[]),
+                    false,
+                    false,
+                )
+            }
+            &Language::ShapeOf([id]) => match &egraph[id].data {
+                MyAnalysisData::Shape(s) => MyAnalysisData::Shape(s.clone()),
+                MyAnalysisData::AccessPattern(a) => MyAnalysisData::Shape(ShapeData {
+                    shape: IxDyn(&a.as_vec()),
+                    dtype: DataType::Float(32),
+                }),
+                other => panic!("expected a tensor, found {:?}", other),
+            },
+            &Language::SliceShape([shape_id, dim_id]) => {
+                let dim = MyAnalysis::get_usize(dim_id, egraph);
+                let (shape, dtype) = match &egraph[shape_id].data {
+                    MyAnalysisData::Shape(s) => (s.shape.slice().to_vec(), s.dtype),
+                    MyAnalysisData::AccessPattern(a) => (a.as_vec(), DataType::Uint(64)),
+                    other => panic!("expected a shape, found {:?}", other),
+                };
+                MyAnalysisData::Shape(ShapeData {
+                    shape: IxDyn(&shape[dim..]),
+                    dtype,
+                })
+            }
+            &Language::ShapeInsertAxis([shape_id, axis_id]) => {
+                let axis = MyAnalysis::get_usize(axis_id, egraph);
+                let s = match &egraph[shape_id].data {
+                    MyAnalysisData::Shape(s) => s,
+                    other => panic!("expected a shape, found {:?}", other),
+                };
+                assert!(axis <= s.shape.ndim());
+                let mut shape = s.shape.slice().to_vec();
+                shape.insert(axis, 1);
+                MyAnalysisData::Shape(ShapeData {
+                    shape: IxDyn(&shape),
+                    dtype: s.dtype,
+                })
+            }
+            &Language::ShapeRemoveAxis([shape_id, axis_id]) => {
+                let axis = MyAnalysis::get_usize(axis_id, egraph);
+                let s = match &egraph[shape_id].data {
+                    MyAnalysisData::Shape(s) => s,
+                    other => panic!("expected a shape, found {:?}", other),
+                };
+                assert!(axis < s.shape.ndim(), "invalid axis in shape-remove-axis");
+                let mut shape = s.shape.slice().to_vec();
+                shape.remove(axis);
+                MyAnalysisData::Shape(ShapeData {
+                    shape: IxDyn(&shape),
+                    dtype: s.dtype,
+                })
+            }
+            &Language::AccessTensor(id) => match &egraph[id].data {
+                MyAnalysisData::Shape(s) => aa_access_data(s.shape.clone(), IxDyn(&[]), true, false),
+                MyAnalysisData::Literal(l) => {
+                    aa_access_data(IxDyn(l.shape()), IxDyn(&[]), true, false)
+                }
+                other => panic!("expected a tensor, found {:?}", other),
+            },
+            &Language::Access([access_id, dim_id]) => {
+                let a = aa_access(egraph, access_id);
+                let dim = MyAnalysis::get_usize(dim_id, egraph);
+                let full = a.as_vec();
+                assert!(dim <= full.len(), "access axis out of range");
+                aa_access_from_vec(
+                    &full,
+                    dim,
+                    a.access_pattern_shape_settled,
+                    a.contains_accelerator_calls,
+                )
+            }
+            &Language::AccessTranspose([access_id, list_id]) => {
+                let a = aa_access(egraph, access_id);
+                let order = match &egraph[list_id].data {
+                    MyAnalysisData::List(l) => l,
+                    other => panic!("expected a list, found {:?}", other),
+                };
+                let full = a.as_vec();
+                assert_eq!(order.len(), full.len(), "transpose list has the wrong length");
+                let permuted = order.iter().map(|&i| full[i]).collect::<Vec<_>>();
+                aa_access_from_vec(
+                    &permuted,
+                    a.shape.ndim(),
+                    a.access_pattern_shape_settled,
+                    a.contains_accelerator_calls,
+                )
+            }
+            &Language::AccessCartesianProduct([a0_id, a1_id]) => {
+                let a0 = aa_access(egraph, a0_id);
+                let a1 = aa_access(egraph, a1_id);
+                assert_eq!(
+                    a0.item_shape, a1.item_shape,
+                    "cartesian product argument item shapes must match"
+                );
+                let shape = a0
+                    .shape
+                    .slice()
+                    .iter()
+                    .chain(a1.shape.slice().iter())
+                    .cloned()
+                    .collect::<Vec<_>>();
+                let item_shape = std::iter::once(2)
+                    .chain(a0.item_shape.slice().iter().cloned())
+                    .collect::<Vec<_>>();
+                aa_access_data(
+                    IxDyn(&shape),
+                    IxDyn(&item_shape),
+                    a0.access_pattern_shape_settled && a1.access_pattern_shape_settled,
+                    a0.contains_accelerator_calls || a1.contains_accelerator_calls,
+                )
+            }
+            &Language::Compute(ids) => aa_compute(egraph, ids),
+            &Language::AccessWindows([access_id, filters_id, stride_id]) => {
+                let a = aa_access(egraph, access_id);
+                let filters = MyAnalysis::get_shape_of_value(filters_id, egraph);
+                let stride = MyAnalysis::get_shape_of_value(stride_id, egraph);
+                assert_eq!(
+                    a.item_shape.ndim(),
+                    filters.ndim(),
+                    "access-windows window rank must match the item rank"
+                );
+                assert!(stride.slice().iter().all(|&s| s > 0));
+                let windows = access_windows_resulting_shape(&a.item_shape, filters, stride);
+                let shape = a
+                    .shape
+                    .slice()
+                    .iter()
+                    .chain(windows.iter())
+                    .cloned()
+                    .collect::<Vec<_>>();
+                aa_access_data(
+                    IxDyn(&shape),
+                    filters.clone(),
+                    a.access_pattern_shape_settled,
+                    a.contains_accelerator_calls,
+                )
+            }
+            &Language::AccessPad([access_id, pad_type_id, axis_id, before_id, after_id]) => {
+                let a = aa_access(egraph, access_id);
+                match &egraph[pad_type_id].data {
+                    MyAnalysisData::PadType(_) => (),
+                    other => panic!("expected a pad type, found {:?}", other),
+                }
+                let axis = MyAnalysis::get_usize(axis_id, egraph);
+                let before = MyAnalysis::get_usize(before_id, egraph);
+                let after = MyAnalysis::get_usize(after_id, egraph);
+                let mut full = a.as_vec();
+                assert!(axis < full.len(), "pad axis out of range");
+                full[axis] += before + after;
+                aa_access_from_vec(
+                    &full,
+                    a.shape.ndim(),
+                    a.access_pattern_shape_settled,
+                    a.contains_accelerator_calls,
+                )
+            }
+            &Language::AccessSqueeze([access_id, axis_id]) => {
+                let a = aa_access(egraph, access_id);
+                let axis = MyAnalysis::get_usize(axis_id, egraph);
+                let mut full = a.as_vec();
+                assert!(axis < full.len(), "squeeze axis out of range");
+                assert_eq!(full[axis], 1, "cannot squeeze an axis which is not equal to 1");
+                full.remove(axis);
+                let access_axis = if axis < a.shape.ndim() {
+                    a.shape.ndim() - 1
+                } else {
+                    a.shape.ndim()
+                };
+                aa_access_from_vec(
+                    &full,
+                    access_axis,
+                    a.access_pattern_shape_settled,
+                    a.contains_accelerator_calls,
+                )
+            }
+            &Language::AccessInsertAxis([access_id, axis_id]) => {
+                let a = aa_access(egraph, access_id);
+                let axis = MyAnalysis::get_usize(axis_id, egraph);
+                let mut full = a.as_vec();
+                assert!(axis <= full.len(), "insert axis out of range");
+                full.insert(axis, 1);
+                let access_axis = if axis <= a.shape.ndim() {
+                    a.shape.ndim() + 1
+                } else {
+                    a.shape.ndim()
+                };
+                aa_access_from_vec(
+                    &full,
+                    access_axis,
+                    a.access_pattern_shape_settled,
+                    a.contains_accelerator_calls,
+                )
+            }
+            &Language::AccessConcatenate([a0_id, a1_id, axis_id]) => {
+                let a0 = aa_access(egraph, a0_id);
+                let a1 = aa_access(egraph, a1_id);
+                let axis = MyAnalysis::get_usize(axis_id, egraph);
+                let mut full = a0.as_vec();
+                let other = a1.as_vec();
+                assert_eq!(a0.shape.ndim(), a1.shape.ndim());
+                assert_eq!(full.len(), other.len());
+                assert!(axis < full.len(), "concatenation axis out of range");
+                for (i, (x, y)) in full.iter().zip(other.iter()).enumerate() {
+                    assert!(i == axis || x == y, "concatenated accesses must match off-axis");
+                }
+                full[axis] += other[axis];
+                aa_access_from_vec(
+                    &full,
+                    a0.shape.ndim(),
+                    a0.access_pattern_shape_settled && a1.access_pattern_shape_settled,
+                    a0.contains_accelerator_calls || a1.contains_accelerator_calls,
+                )
+            }
+            &Language::AccessSlice([access_id, axis_id, low_id, high_id]) => {
+                let a = aa_access(egraph, access_id);
+                let axis = MyAnalysis::get_usize(axis_id, egraph);
+                let low = MyAnalysis::get_usize(low_id, egraph);
+                let high = MyAnalysis::get_usize(high_id, egraph);
+                let mut full = a.as_vec();
+                assert!(axis < full.len(), "slice axis out of range");
+                assert!(low <= high && high <= full[axis], "slice out of bounds");
+                full[axis] = high - low;
+                aa_access_from_vec(
+                    &full,
+                    a.shape.ndim(),
+                    a.access_pattern_shape_settled,
+                    a.contains_accelerator_calls,
+                )
+            }
+            &Language::AccessPair([a0_id, a1_id]) => {
+                let a0 = aa_access(egraph, a0_id);
+                let a1 = aa_access(egraph, a1_id);
+                assert_eq!(a0.shape, a1.shape, "paired accesses must have equal shapes");
+                assert_eq!(a0.item_shape, a1.item_shape, "paired accesses must have equal item shapes");
+                let item_shape = std::iter::once(2)
+                    .chain(a0.item_shape.slice().iter().cloned())
+                    .collect::<Vec<_>>();
+                aa_access_data(
+                    a0.shape.clone(),
+                    IxDyn(&item_shape),
+                    a0.access_pattern_shape_settled && a1.access_pattern_shape_settled,
+                    a0.contains_accelerator_calls || a1.contains_accelerator_calls,
+                )
+            }
+            &Language::AccessShiftRight(access_id) => {
+                let a = aa_access(egraph, access_id);
+                aa_access_from_vec(
+                    &a.as_vec(),
+                    a.shape.ndim().saturating_sub(1),
+                    a.access_pattern_shape_settled,
+                    a.contains_accelerator_calls,
+                )
+            }
+            &Language::AccessFlatten(access_id) => {
+                let a = aa_access(egraph, access_id);
+                aa_access_data(
+                    IxDyn(&[a.shape.size()]),
+                    IxDyn(&[a.item_shape.size()]),
+                    a.access_pattern_shape_settled,
+                    a.contains_accelerator_calls,
+                )
+            }
+            &Language::AccessShape([shape_id, item_shape_id]) => aa_access_data(
+                MyAnalysis::get_shape_of_value(shape_id, egraph).clone(),
+                MyAnalysis::get_shape_of_value(item_shape_id, egraph).clone(),
+                true,
+                false,
+            ),
+            &Language::GetAccessShape([access_id]) => {
+                let a = aa_access(egraph, access_id);
+                aa_access_data(
+                    a.shape.clone(),
+                    a.item_shape.clone(),
+                    a.access_pattern_shape_settled,
+                    a.contains_accelerator_calls,
+                )
+            }
+            &Language::AccessReshape([access_id, shape_id]) => {
+                let a = aa_access(egraph, access_id);
+                let s = aa_access(egraph, shape_id);
+                aa_access_data(
+                    s.shape.clone(),
+                    s.item_shape.clone(),
+                    a.access_pattern_shape_settled && s.access_pattern_shape_settled,
+                    a.contains_accelerator_calls || s.contains_accelerator_calls,
+                )
+            }
+            &Language::AccessBroadcast([access_id, shape_id]) => {
+                let a = aa_access(egraph, access_id);
+                let s = aa_access(egraph, shape_id);
+                let full = a.as_vec();
+                let target = s.as_vec();
+                assert_eq!(full.len(), target.len(), "broadcast ranks must match");
+                for (x, y) in full.iter().zip(target.iter()) {
+                    assert!(*x == 1 || x == y, "cannot broadcast {:?} to {:?}", full, target);
+                }
+                aa_access_from_vec(
+                    &target,
+                    a.shape.ndim(),
+                    a.access_pattern_shape_settled && s.access_pattern_shape_settled,
+                    a.contains_accelerator_calls || s.contains_accelerator_calls,
+                )
+            }
+            &Language::SystolicArray(ids) => aa_systolic_array(egraph, false, ids),
+            &Language::SystolicArrayWithBlocking(ids) => aa_systolic_array(egraph, true, ids),
+            Language::SystolicArrayConv2dNchwOihwWithBlocking(ids)
+            | Language::SystolicArrayConv2dIm2colNchwOihwWithBlocking(ids) => {
+                aa_systolic_array_conv2d(egraph, false, ids)
+            }
+            Language::SystolicArrayConv2dNhwcHwioWithBlocking(ids)
+            | Language::SystolicArrayConv2dIm2colNhwcHwioWithBlocking(ids) => {
+                aa_systolic_array_conv2d(egraph, true, ids)
+            }
+            Language::RelayOperatorCall(params) => aa_relay_operator_call(egraph, params),
+            Language::AcceleratorCall(ids) => aa_accelerator_call(egraph, ids),
+        }
     }
 }
